WITH agg AS (SELECT p.p_promo_sk, p.p_promo_name, CASE WHEN p.p_discount_active = 'Y' THEN 'Active' ELSE 'Inactive' END AS discount_status, SUM(cs.cs_net_paid) AS total_paid, SUM(cr.cr_refunded_cash) AS total_refunded, SUM(cs.cs_net_paid) - SUM(cr.cr_refunded_cash) AS net_cash_flow, AVG(t_return.t_time - t_sale.t_time) AS avg_time_diff_seconds FROM promotion p JOIN catalog_sales cs ON cs.cs_promo_sk = p.p_promo_sk JOIN catalog_returns cr ON cr.cr_order_number = cs.cs_order_number AND cr.cr_item_sk = cs.cs_item_sk JOIN time_dim t_sale ON cs.cs_sold_time_sk = t_sale.t_time_sk JOIN time_dim t_return ON cr.cr_returned_time_sk = t_return.t_time_sk WHERE p.p_channel_email = 'Y' GROUP BY p.p_promo_sk, p.p_promo_name, CASE WHEN p.p_discount_active = 'Y' THEN 'Active' ELSE 'Inactive' END HAVING SUM(cs.cs_net_paid) > 1000) SELECT agg.p_promo_sk, agg.p_promo_name, agg.discount_status, agg.total_paid, agg.total_refunded, agg.net_cash_flow, agg.avg_time_diff_seconds, ROW_NUMBER() OVER (ORDER BY agg.net_cash_flow DESC) AS cash_flow_rank FROM agg ORDER BY agg.net_cash_flow DESC LIMIT 5
